{
  "name": "PV位置器软件组件",
  "name_en": "PV Positioner Software Component",
  "manufacturer": "",
  "description": "非物理的软件组件，用于将一个或多个过程变量（PV）组织成统一的位置器接口。它提供设定值写入、读回监视、软限位检查、停止控制、运动状态与完成状态判断等能力，常用于实验自动化中把电机、执行器或一般位置型PV封装为可移动对象。",
  "description_en": "A non-physical software component that organizes one or more process variables (PVs) into a unified positioner interface. It provides setpoint writes, readback monitoring, soft-limit checks, stop control, motion-state reporting, and move-completion logic, and is commonly used in experimental automation to represent motors, actuators, or general position-like PVs as movable objects.",
  "tag_hints": [
    "EPICS PV control",
    "positioner abstraction",
    "motion setpoint/readback",
    "soft limits",
    "move completion logic",
    "experimental automation"
  ],
  "actions": [
    {
      "action_name": "auto-check_value",
      "description": "检查请求位置是否在软限位范围内。",
      "description_en": "Check whether the requested position is within the soft limits."
    },
    {
      "action_name": "auto-move",
      "description": "通过PV发起移动到目标位置，并可选择等待完成。",
      "description_en": "Initiate a move to the target position through PVs, optionally waiting for completion."
    },
    {
      "action_name": "auto-stop",
      "description": "通过停止信号中止当前移动。",
      "description_en": "Stop the current move using the configured stop signal."
    },
    {
      "action_name": "auto-egu",
      "description": "获取位置的工程单位。",
      "description_en": "Get the engineering units for position."
    },
    {
      "action_name": "auto-put_complete",
      "description": "获取是否使用异步写入完成作为完成判定。",
      "description_en": "Get whether asynchronous put completion is used to determine move completion."
    },
    {
      "action_name": "auto-moving",
      "description": "获取是否正在移动。",
      "description_en": "Get whether motion is in progress."
    },
    {
      "action_name": "auto-report",
      "description": "获取位置器状态报告。",
      "description_en": "Get the positioner status report."
    },
    {
      "action_name": "auto-limits",
      "description": "获取位置软限位范围。",
      "description_en": "Get the position soft-limit range."
    },
    {
      "action_name": "auto-done_comparator",
      "description": "获取用于判断移动完成的比较规则。",
      "description_en": "Get the comparison rule used to determine move completion."
    }
  ]
}

